package dev.alex.fyt.probe.tests;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import dev.alex.fyt.probe.*;
/** Native guide placement and modal interactions; local source data only. */
public final class PlayerControlsHelpTests extends Instrumentation {
 private final ProbeState state=ProbeState.INSTANCE;private Activity activity;private int checks;
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 private Object field(String name)throws Exception{java.lang.reflect.Field f=AudioPlayerActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
 private void touch(View v){int[] xy=new int[2];runOnMainSync(()->v.getLocationOnScreen(xy));long now=SystemClock.uptimeMillis();for(int a:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(now,SystemClock.uptimeMillis(),a,xy[0]+v.getWidth()/2f,xy[1]+v.getHeight()/2f,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(e,true),"physical touch delivered");e.recycle();}waitForIdleSync();SystemClock.sleep(180);}
 private void image(Context c,String name)throws Exception{waitForIdleSync();SystemClock.sleep(500);Bitmap b=getUiAutomation().takeScreenshot();try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void setup(int index){state.newSession();state.running(true);state.status("test","local controls fixture",true);state.event(1000,new int[]{6291908},null,null);state.event(98,new int[]{index==0?1:index==1||index==3?2:4},null,null);if(index==3)state.event(1019,new int[]{46,6,3,50,34,34,128},null,null);if(index==0){state.event(115,new int[]{1},null,null);state.event(119,new int[]{241},null,null);}}
 private void close(){if(activity!=null){runOnMainSync(()->activity.finish());waitForIdleSync();activity=null;}SystemClock.sleep(180);}
 @Override public void onStart(){Context c=getTargetContext();String theme=ThemeSettings.mode(c),lang=I18n.language(c);Bundle result=new Bundle();int outcome=Activity.RESULT_OK;
  try{c.stopService(new Intent(c,ProbeService.class));SystemClock.sleep(300);int[] content={R.string.player_controls_radio,R.string.player_controls_cd,R.string.player_controls_usb,R.string.player_controls_ipod};
   for(String mode:new String[]{ThemeSettings.DAY,ThemeSettings.NIGHT})for(String language:new String[]{"en","ru"})for(int i=0;i<4;i++){
    I18n.language(c,language);ThemeSettings.mode(c,mode);setup(i);activity=startActivitySync(AudioPlayerActivity.intent(c,i==0?AudioMode.RADIO:i==1?AudioMode.CD:AudioMode.USB,false));waitForIdleSync();SystemClock.sleep(200);
    ImageButton info=(ImageButton)field("playerInfo");View panel=(View)info.getParent();float density=c.getResources().getDisplayMetrics().density;
    check(info.isShown()&&info.isEnabled(),"controls icon shown on source "+i);check(info.getContentDescription().toString().equals(I18n.t(R.string.player_controls_help_description)),"localized controls accessibility label");check(Math.abs(info.getTop()-8*density)<1&&Math.abs(panel.getWidth()-info.getRight()-8*density)<1,"controls icon anchored at panel top right");check(Math.abs(info.getWidth()-44*density)<1,"44dp touch target");
    if(i==2&&language.equals("en"))image(c,"player-controls-icon-"+mode+"-TEST.png");touch(info);AlertDialog dialog=(AlertDialog)field("playerHelp");check(dialog!=null&&dialog.isShowing(),"guide opens");String message=((TextView)dialog.findViewById(android.R.id.message)).getText().toString();check(message.contains(I18n.t(content[i]))&&message.contains(I18n.t(R.string.player_controls_source))&&message.contains(I18n.t(R.string.player_controls_settings)),"source-specific guide includes source and audio settings");Button done=dialog.getButton(AlertDialog.BUTTON_POSITIVE);Rect bounds=new Rect();check(done.getGlobalVisibleRect(bounds)&&bounds.height()>0,"close button remains visible with long guide");
    if(i==2&&language.equals("en"))image(c,"player-controls-help-"+mode+"-TEST.png");touch(done);check(!dialog.isShowing(),"guide closes");check(!state.snapshot().commandBusy,"guide sends no command");close();
   }
   I18n.language(c,"en");setup(3);activity=startActivitySync(AudioPlayerActivity.intent(c,AudioMode.USB,false));waitForIdleSync();runOnMainSync(()->activity.findViewById(android.R.id.content).findViewWithTag("player-controls-info").performClick());AlertDialog first=(AlertDialog)field("playerHelp");runOnMainSync(()->activity.findViewById(android.R.id.content).findViewWithTag("player-title-info").performClick());check(!first.isShowing()&&((AlertDialog)field("titleHelp")).isShowing(),"TITLE tip replaces controls guide");AlertDialog title=(AlertDialog)field("titleHelp");runOnMainSync(()->activity.findViewById(android.R.id.content).findViewWithTag("player-controls-info").performClick());check(!title.isShowing()&&((AlertDialog)field("playerHelp")).isShowing(),"controls guide replaces TITLE tip");AlertDialog last=(AlertDialog)field("playerHelp");ThemeSettings.mode(c,ThemeSettings.DAY);runOnMainSync(()->{try{java.lang.reflect.Method render=AudioPlayerActivity.class.getDeclaredMethod("render");render.setAccessible(true);render.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});check(!last.isShowing()&&field("playerHelp")==null,"theme rebuild closes old guide");
   result.putString("result","PASS: "+checks+" player controls guide UI checks");
  }catch(Throwable e){outcome=1;result.putString("failure",android.util.Log.getStackTraceString(e));}finally{close();state.newSession();state.running(false);I18n.language(c,lang);ThemeSettings.mode(c,theme);}finish(outcome,result);
 }
}
